<template><div class="settings-grid"><a-card class="panel-card" title="从备份记录恢复"><a-form layout="vertical"><a-form-item label="备份记录"><a-select v-model:value="recordId" :options="options" placeholder="请选择备份"/></a-form-item><a-alert type="warning" show-icon message="恢复会覆盖当前数据库，请先做好额外备份"/><a-popconfirm title="确定恢复所选备份？" @confirm="restore"><a-button danger style="margin-top:20px" :disabled="!recordId">开始恢复</a-button></a-popconfirm></a-form></a-card><a-card class="panel-card" title="上传备份恢复"><a-upload-dragger :before-upload="selectFile" :max-count="1" accept=".zip"><InboxOutlined/><p>点击或拖拽 ZIP 备份文件</p></a-upload-dragger><a-popconfirm title="确定上传并恢复？" @confirm="upload"><a-button danger style="margin-top:20px" :disabled="!file">上传并恢复</a-button></a-popconfirm></a-card></div></template><script setup lang="ts">import{computed,onMounted,ref}from'vue';import{message}from'ant-design-vue';import{InboxOutlined}from'@ant-design/icons-vue';import{get,post,request}from'../../services/http';import{formatTime}from'../../core/format';import type{AnyMap,BackupRecord}from'../../types';const records=ref<BackupRecord[]>([]),recordId=ref<number>(),file=ref<File>();const options=computed(()=>records.value.map(r=>({value:r.id,label:`#${r.id} · ${formatTime(r.created_at)}`})));onMounted(async()=>{const d=await get<AnyMap>('/backup/list?page=1&page_size=100');records.value=d.list||[]});async function restore(){await post('/backup/restore',{record_id:recordId.value});message.success('恢复任务已启动')}function selectFile(f:File){file.value=f;return false}async function upload(){const data=new FormData();data.append('file',file.value!);await request('/backup/upload-restore',{method:'POST',body:data});message.success('上传成功，恢复任务已启动')}</script>
